function fitStoryReading(){
 const host=$('club-story-dialog');if(!host.open)return;const body=host.querySelector('.story-reading');if(!body)return;
 let size=innerHeight<360?11:13;body.style.setProperty('--story-prose-size',size+'px');
 while(size>8&&body.scrollHeight>body.clientHeight+1){size-=.5;body.style.setProperty('--story-prose-size',size+'px');}
 for(const button of host.querySelectorAll('.story-choices button,[data-story-action]')){
  if(!button.checkVisibility())continue;button.style.removeProperty('font-size');let font=parseFloat(getComputedStyle(button).fontSize);
  while(font>8&&(button.scrollHeight>button.clientHeight+1||button.scrollWidth>button.clientWidth+1)){font-=.5;button.style.fontSize=font+'px';}
 }
 if(typeof ClubArt!=='undefined')ClubArt.fitDrama?.(host);
}
// Optional story choices are campaign data; onboarding completion remains a device preference.
var clubStoryEvent=null,clubStoryOpener=null,clubStoryExpected=null,clubStoryRequired=false,clubStoryPage=0,clubStoryPageStamp=null,clubStoryNotebookReturn=null;
const storyRelationNames={board:'구단주',coach:'코치',captain:'선수단',rookie:'유망주',fans:'팬'};
function storyMissionText(m){return m.year+'시즌 리그 '+m.end+'경기까지 · 출전 '+m.minutes+'/'+m.target+'분 · '+{active:'약속 진행 중',fulfilled:'약속을 지켰습니다',missed:'출전 약속을 지키지 못했습니다'}[m.status];}
function storyPromiseMarkup(m){
 const stateText=!m.slot?'현재 선수단에 없습니다.':!m.available?'현재 출전할 수 없습니다. 몸 상태와 출전 조건을 확인하세요.':(m.starting?'현재 선발':'현재 후보')+' · 체력 '+Math.round(m.energy);
 return '<section class="story-promise" aria-label="출전 약속 진행"><strong>'+escapeText(m.name)+'과의 출전 약속</strong><p>'+escapeText(storyMissionText(m))+'</p><progress max="'+m.target+'" value="'+Math.min(m.target,m.minutes)+'" aria-label="확정 출전 '+m.minutes+'분 / 목표 '+m.target+'분"></progress><small>'+(m.status==='active'?'남은 리그 '+m.remainingGames+'경기 · '+m.remainingMinutes+'분 필요 · ':'')+escapeText(stateText)+'</small><ol class="story-promise-games" aria-label="약속한 두 리그 경기">'+m.games.map(g=>'<li><span>리그 '+g.round+'R · '+escapeText(g.opponent?S.club(g.opponent).short:'상대 확인 대기')+'</span><strong>'+(g.confirmed?g.minutes+'분 출전':'경기 대기')+'</strong></li>').join('')+'</ol>'+(m.livePending?'<p class="story-promise-live" role="status">현재 경기 '+m.liveMinutes+'분 출전 · 결과 확정 후 약속에 반영됩니다.</p>':m.competition!=='league'&&m.status==='active'?'<p class="story-promise-live">컵·유럽 경기 출전은 리그 출전 약속에 포함되지 않습니다.</p>':'')+'<div>'+(m.slot&&m.status==='active'?'<button type="button" data-story-plan>선발·교체 계획 확인</button>':'')+(m.followupReady?'<button type="button" data-story-event="'+m.event+'">약속 후속 면담</button>':'')+'</div></section>';
}
function storyInboxPriority(pending){const priority=e=>e.key==='memory-warning'?0:e.key?.startsWith('contract-result-')?1:e.key?.startsWith('memory-')?2:(e.key?.startsWith('serial-')||e.key?.startsWith('thread-'))?3:e.key?.startsWith('notebook-')?4:5;return [...pending].sort((a,b)=>(b.step===1)-(a.step===1)||priority(a)-priority(b)||b.round-a.round||Number(b.key?.startsWith('signing-'))-Number(a.key?.startsWith('signing-'))||a.id.localeCompare(b.id));}
function renderClubStory(){
 if(view!=='club')return;const host=$('club-story-panel'),d=ClubStory.read(season),inbox=storyInboxPriority(d.pending),next=inbox[0],mission=d.promises.filter(m=>m.current).at(-1);
 host.innerHTML='<div class="story-heading"><div><small>구단 이야기</small><h2>'+(d.readOnly?'끝난 삶의 이야기':'감독님께 도착한 대화')+'</h2></div><button type="button" data-story-notebook aria-label="감독의 수첩 펼치기">수첩</button><span>'+d.pending.length+(d.readOnly?'건 미완료 기록':'건 대기')+'</span></div><p>'+(d.readOnly?'끝난 삶에서는 당시 도착한 이야기를 읽을 수 있습니다. 새 대답은 다음 삶에서 이어집니다.':next?escapeText(next.speaker)+'에게서 새로운 이야기가 도착했습니다. 다음 경기 전에 들어보세요.':'이번 대화를 모두 마쳤습니다. 경기 결과와 시즌 진행에 따라 다음 이야기가 도착합니다.')+'</p>'+(next?'<button type="button" id="club-story-open" class="primary">'+escapeText(next.title)+(d.readOnly?' · 기록 읽기':next.step===1?' · 대화 이어가기':' · 대화하기')+'</button>':'')+(inbox.length>1?'<div class="story-recent" aria-label="최근 도착한 대화">'+inbox.slice(1,3).map(e=>'<button type="button" class="secondary" data-story-event="'+e.id+'">'+escapeText(e.title)+'<small>'+escapeText(e.speaker)+' · '+e.round+'경기 이후'+(e.step===1?' · 대화 진행 중':'')+'</small></button>').join('')+'</div>':'')+'<div class="story-relations">'+Object.entries(d.relationships).map(([key,value])=>'<span>'+storyRelationNames[key]+' <b>'+value+'</b></span>').join('')+'</div>'+(mission?storyPromiseMarkup(mission):'')+'<details><summary>대기 이벤트와 지난 대화</summary><div class="story-event-list">'+inbox.map(e=>'<button type="button" data-story-event="'+e.id+'">'+escapeText(e.title)+'<small>'+escapeText(e.speaker)+' · '+e.round+'경기 이후</small></button>').join('')+'</div><ol class="story-history">'+d.history.slice(-6).reverse().map(h=>'<li><button type="button" data-story-event="'+h.id+'">'+escapeText(h.title)+' · 다시 읽기</button><span>'+h.year+'시즌 · '+h.round+'경기 완료 시점 · '+escapeText(h.actor)+'</span><small>'+(h.choice==='commit'?'방향을 지키겠다고 약속했습니다.':'조건을 설명하고 함께 점검하기로 했습니다.')+'</small>'+(h.mission?'<small>'+escapeText(storyMissionText(h.mission))+'</small>':'')+'</li>').join('')+'</ol></details><small>대화를 마치면 선수별 경기 집중 반응을 확인합니다. 서사 효과의 합계는 최대 ±2%이며 일시적으로 적용됩니다.</small>';
 host.onclick=event=>{const notebook=event.target.closest('[data-story-notebook]');if(notebook){openManagerNotebook(notebook);return;}const plan=event.target.closest('[data-story-plan]');if(plan){const player=Object.values(state?.players||{}).find(p=>p.identity===mission?.identity);if(player)selected=state.lineup.includes(player.id)?player.id:null;setView('match');openMatchPopup(state?.phase==='prep'?'tactics':'roster',plan);return;}const b=event.target.closest('[data-story-event]');if(b)openClubStory(b.dataset.storyEvent,b);else if(event.target.closest('#club-story-open'))openClubStory(next.id,$('club-story-open'));};
}
function openClubStory(event,opener=document.activeElement,required=false,notebookContext=null){
 if(typeof practiceSession!=='undefined'&&practiceSession){notify('전술 연습을 마친 뒤 구단 대화를 확인하세요.');return;}
 const opening=ClubStory.scene(season,event);if(!opening)return;pauseForPlanning();save();clubStoryEvent=event;clubStoryOpener=opener;clubStoryRequired=required;clubStoryNotebookReturn=notebookContext;clubStoryPage=0;clubStoryPageStamp=opening.step===2?opening.id+':2':null;renderClubStoryDialog();$('club-story-dialog').showModal();fitStoryReading();
}
function storyIllustration(d){if(d.art)return d.art;if(d.key.startsWith('memory-'))return d.key==='memory-warning'?'office':'rebirth';if(d.key==='tier')return /강등|다시 도전/.test(d.title)?'rain':'growth';return {arrival:'office',captain:'locker',rookie:'locker',fans:'rain',community:'arrival','three-losses':'rain','bounce-back':'locker'}[d.key]||null;}
function storyArtwork(d){return d.artThread?ClubArt.thread(d.artThread,d.serial?.episode===3):d.drama&&ClubArt.drama?ClubArt.drama(d.drama,d.serial?.episode===3):ClubArt.memory(storyIllustration(d)||'locker');}
function storySerialContext(d){if(!d.serial)return '';return '<aside class="story-serial-context" aria-label="이어지는 이야기와 확정 기록"><strong>'+escapeText(d.serial.title)+' · '+d.serial.episode+'/3화</strong><dl class="story-evidence">'+d.serial.facts.map(([label,value])=>'<div><dt>'+escapeText(label)+'</dt><dd>'+escapeText(value)+'</dd></div>').join('')+'</dl><small>'+escapeText(d.step===2?storyRelationNames[d.relation]+' 관계 '+d.relationScore+' · 대화 반응 기록 완료':'경기·선발·자금은 직접 결정한 내용만 반영됩니다.')+'</small></aside>';}
function storySceneCards(text,compact=false){const chunks=String(text).split(compact?/\n+/:/\n\n+/).filter(Boolean);return chunks.length?chunks.map(t=>({speaker:'장면',text:t})): [{speaker:'장면',text}];}
function compactStoryReading(d){return d.readingVersion===2||!d.serial&&typeof innerHeight==='number'&&innerHeight<300;}
function clubStoryPages(d){
 if(typeof ManagerVoice!=='undefined')return ManagerVoice.pages(compactStoryReading(d)?{...ManagerVoice.story(season,d),readingVersion:2}:ManagerVoice.story(season,d),{limit:d.serial?(innerHeight<350?340:innerWidth<740?430:innerHeight<400?540:700):innerHeight<300?340:innerWidth<740?470:700});
 if(d.step===0)return [...storySceneCards(d.scene,d.key.startsWith('notebook-')),{speaker:d.questionSpeaker||d.name,text:d.question}];
 if(d.step===1)return [{speaker:d.name,text:d.reaction},{speaker:d.name,text:d.question}];
 const original=ClubStory.events(season,d.year).find(e=>e.id===d.id),first=d.answered[0];
 return [...storySceneCards(d.scene,d.key.startsWith('notebook-')),{speaker:original.questionSpeaker||d.name,text:original.question},{speaker:'감독',text:d.options[['listen','bold','practical'].indexOf(first.choice)]},{speaker:d.name,text:d.reaction},{speaker:d.name,text:d.question},{speaker:'감독',text:d.finalLabel},{speaker:d.name,text:d.reply},...(d.impact?String(d.impact).split(d.key.startsWith('notebook-')?/\n+/:/$^/).filter(Boolean).map(text=>({speaker:'경기력 반영',text})):[])];
}
function renderStoryPage(d){
 const host=$('club-story-dialog'),pages=clubStoryPages(d),stamp=d.id+':'+d.step;
 if(stamp!==clubStoryPageStamp){clubStoryPageStamp=stamp;const replyPage=pages.findIndex(p=>p.kind==='complete-reply');clubStoryPage=d.step===2?(typeof ManagerVoice==='undefined'?Math.max(0,pages.findLastIndex(p=>p.speaker===d.name&&p.text===d.reply)):replyPage>=0?replyPage:pages.length-1):0;}
 clubStoryPage=Math.max(0,Math.min(pages.length-1,clubStoryPage));const page=pages[clubStoryPage],arrivalDone=clubStoryRequired&&d.step===2,last=arrivalDone||clubStoryPage===pages.length-1;
 host.dataset.storyPageKind=page.speaker==='장면'?'scene':'dialogue';
 const sceneArt=storyIllustration(d),speakerRow=host.querySelector('.story-speaker');
 if(speakerRow){const manager=page.speaker==='감독',profile=!manager?F.identityProfile(d.actor):null;speakerRow.innerHTML=(profile?Portraits.html(profile):ClubArt.voice(manager?'manager':d.relation))+'<div><b>'+escapeText(manager?'감독':d.name)+'</b><small>'+escapeText(manager?'내가 남긴 대답':d.speaker+' · '+(d.context||d.memory))+'</small></div>';}

 const body=page.blocks?page.blocks.map(b=>'<section data-story-speaker="'+escapeText(b.speaker)+'" class="story-block '+(b.speaker==='속마음'?'story-thought':'')+'"><b>'+escapeText(b.speaker==='속마음'?'(속마음)':b.speaker)+'</b><p>'+escapeText(b.text)+'</p></section>').join(''):'<p class="story-bubble story-current"><b>'+escapeText(page.speaker)+'</b>'+escapeText(page.text)+'</p>';
 host.querySelector('.story-conversation').innerHTML='<div class="story-reading" aria-live="polite">'+body+(d.mission&&last?'<p class="story-mission">'+escapeText(storyMissionText(d.mission))+'</p>':'')+'</div><nav class="story-page-nav" aria-label="대화 장면 이동"><button type="button" data-story-page="previous" '+(clubStoryPage===0?'disabled':'')+'>이전</button><span>'+(arrivalDone?'면담 완료':pages.length===1?'읽고 직접 대답하기':'장면 '+(clubStoryPage+1)+' / '+pages.length)+'</span><button type="button" data-story-page="next" '+(last&&!arrivalDone?'disabled':'')+'>'+(arrivalDone?'다음: 조작 안내':clubStoryPage===pages.length-2&&d.step<2&&!d.readOnly?'대답하기':'다음')+'</button></nav>';
 host.querySelector('.story-choices').hidden=!last;
 const complete=host.querySelector('.story-complete');if(complete)complete.hidden=!last||!!d.serial;
 const action=host.querySelector('[data-story-action]');if(action)action.hidden=(!last&&!((d.serial||compactStoryReading(d))&&page.kind==='complete-reply'))||clubStoryRequired;
}
function renderClubStoryDialog(){
 const original=ClubStory.scene(season,clubStoryEvent),d=typeof ManagerVoice==='undefined'?original:ManagerVoice.story(season,original);if(!d){$('club-story-dialog').close();return;}clubStoryExpected=ClubStory.fingerprint(season);
 const host=$('club-story-dialog'),first=d.answered[0],firstIndex=first?['listen','bold','practical'].indexOf(first.choice):-1,action=d.readOnly?null:d.action|| (d.serial?({keeper:'roster',workload:'health',away:'competition',board:'finance'}[d.serial.id]||null):d.key.startsWith('pressure-')?(['star','private','future'].some(k=>d.key.startsWith('pressure-'+k+'-'))?'roster':'tactics'):['corner-partners','free-kick-memory'].includes(d.key)?'setpieces':['late-goal','outnumbered-result','shape','runin','halfway','marathon','promotion-race','final-push','signing-deadball','three-losses'].includes(d.key)?'tactics':['assist-maker','shared-goals','keeper-night','brace-hero','bounce-back','bench-hero','rookie','promise-kept','promise-missed','signing-welcome','signing-debut'].includes(d.key)?'roster':d.key==='window'?'market':['medical','fans','community','signing-goal','five-unbeaten','cup-night'].includes(d.key)?'squad':d.key==='tier'||d.key==='arrival'?'journey':null);

 const illustration=storyIllustration(d),artKind=['arrival','tier'].includes(d.key)?'arrival':d.relation,matchArt={'assist-maker':'huddle','shared-goals':'huddle','keeper-night':'keeper','brace-hero':'huddle','bounce-back':'rebound','bench-hero':'substitute','signing-debut':'substitute','three-losses':'rebound','outnumbered-result':'huddle'}[d.key];
 host.dataset.storySerial=String(!!d.serial);
 const portrait=F.identityProfile(d.actor);
 host.innerHTML='<header class="story-dialog-head">'+(d.drama?storyArtwork(d):illustration?ClubArt.memory(illustration):['corner-partners','free-kick-memory'].includes(d.key)?ClubArt.deadball(d.key==='corner-partners'?'partnership':'specialist').replace('club-art deadball-art','club-art deadball-art story-art'):matchArt?ClubArt.moment(matchArt).replace('club-art moment-art','club-art moment-art story-art'):ClubArt.story(artKind))+'<div><small>'+(d.serial?'':'구단 이야기 · ')+d.year+'시즌 · '+(d.step===2?'대화 완료':d.serial?(d.step===0?'첫 질문':'마지막 대답'):(d.step+1)+'/2')+'</small><h2 id="club-story-title" tabindex="-1">'+escapeText(d.title)+'</h2>'+(d.readOnly?'<small>'+(d.year!==season.year?'지난 시즌':'끝난 삶')+' 기록 · 읽기 전용</small>':'')+'</div>'+storySerialContext(d)+'<button type="button" data-story-close aria-label="구단 대화 닫기">닫기</button></header><div class="story-speaker">'+(portrait?Portraits.html(portrait):ClubArt.voice(d.relation))+'<div><b>'+escapeText(d.name)+'</b><small>'+escapeText(d.speaker)+' · '+escapeText(d.context||d.memory)+'</small></div></div><div class="story-conversation" tabindex="0" aria-label="현재 대화와 지난 이야기"></div><div class="story-choices" aria-label="감독의 대답">'+d.choices.map(c=>'<button type="button" class="secondary" data-story-choice="'+c.id+'" '+(c.disabled?'disabled':'')+'>'+escapeText(c.label)+(c.disabled?' · '+escapeText(c.reason||'리그 킥오프 전에 가능'):'')+'</button>').join('')+'</div>'+(d.step===2?'<p class="story-complete" role="status">대화 기록 · 현재 '+storyRelationNames[d.relation]+' 관계 '+d.relationScore+'</p>'+(action?'<button type="button" class="primary" data-story-action="'+action+'">'+{setpieces:'세트피스 작전실에서 다음 준비',tactics:'상대·전술·체력 확인하기',roster:'선발·교체 출전 계획 확인하기',market:'영입 보고서 확인하기',squad:'선수단과 컨디션 확인하기',journey:'승격 목표와 시즌 진행 확인하기',health:'몸 상태·휴식과 출전 계획 확인',finance:'재정 장부에서 현재 자금 확인',competition:'대회에서 실제 성적 확인'}[action]+'</button>':''):'')+'<footer><button type="button" class="secondary" data-story-close>'+(clubStoryNotebookReturn?'수첩으로 돌아가기':d.step===2||d.readOnly?'감독실로 돌아가기':'나중에 이어서 대화하기')+'</button><small>'+(d.readOnly?'기록을 읽어도 경기 결과는 바뀌지 않습니다.':'경기는 직접 재개할 때 이어집니다.')+'</small></footer>';

 renderStoryPage(d);fitStoryReading();
 if(clubStoryRequired){host.querySelectorAll('[data-story-close]').forEach(b=>b.hidden=d.step<2);const go=host.querySelector('[data-story-action]');if(go)go.hidden=true;}
 host.onclick=event=>{const page=event.target.closest('[data-story-page]');if(page){if(page.disabled)return;if(clubStoryRequired&&d.step===2&&page.dataset.storyPage==='next'){host.close();return;}clubStoryPage+=page.dataset.storyPage==='next'?1:-1;renderStoryPage(d);fitStoryReading();const next=host.querySelector('[data-story-page="next"]');(next.disabled?host.querySelector('[data-story-choice]:not([disabled])')||host.querySelector('[data-story-page="previous"]'):next).focus({preventScroll:true});return;}const choice=event.target.closest('[data-story-choice]'),close=event.target.closest('[data-story-close]'),go=event.target.closest('[data-story-action]');if(close){if(!clubStoryRequired||d.step===2)host.close();return;}if(go){clubStoryNotebookReturn=null;host.close();const target=go.dataset.storyAction;if(target==='health'||target==='finance'){openManagementPanel(target==='health'?'squad-health':'finance-detail');}else if(target==='competition'){setView('cup');}else if(['tactics','roster','setpieces'].includes(target)&&state){setView('match');openMatchPopup(target,$('primary'));}else if(target==='journey')setView('club');else setView(target==='market'?'market':'squad');return;}if(choice){if(host.querySelector('.story-choices').hidden)return;try{ClubStory.choose(season,d.id,d.step,choice.dataset.storyChoice,clubStoryExpected);save();render();renderClubStoryDialog();$('club-story-title').focus({preventScroll:true});}catch(error){notify(error.message);renderClubStoryDialog();}}};
}
const storyPanel=document.createElement('section');storyPanel.id='club-story-panel';$('manager-journey').after(storyPanel);
const storyDialog=document.createElement('dialog');storyDialog.id='club-story-dialog';storyDialog.setAttribute('aria-labelledby','club-story-title');document.body.append(storyDialog);
storyDialog.addEventListener('cancel',event=>{if(clubStoryRequired&&ClubStory.scene(season,clubStoryEvent)?.step!==2)event.preventDefault();});
storyDialog.addEventListener('close',()=>{if(storyDialog.open)return;const required=clubStoryRequired,notebookContext=clubStoryNotebookReturn;clubStoryNotebookReturn=null;clubStoryRequired=false;clubStoryEvent=null;clubStoryExpected=null;if(required){clubStoryOpener=null;completeManagerArrival();return;}if(notebookContext){clubStoryOpener=null;openManagerNotebook(notebookContext.opener,{tab:notebookContext.tab,page:notebookContext.page,year:notebookContext.year,series:notebookContext.series});return;}if(clubStoryOpener?.isConnected&&!clubStoryOpener.closest('dialog'))clubStoryOpener.focus({preventScroll:true});else $('club-story-open')?.focus({preventScroll:true});clubStoryOpener=null;});
const storyOriginalJourney=renderManagerJourney;renderManagerJourney=function(){storyOriginalJourney();renderClubStory();};
